package com.example.starter.transition.api;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 过渡纸卷登记请求：按卷号唯一登记，登记即强制降级，不得按正品入库。
 *
 * @param requestId 幂等键
 * @param rollNo    卷号（唯一）
 * @param orderNo   所属改品种单号
 * @param lengthM   纸卷长度，单位米
 */
public record RegisterRollRequest(
        @NotBlank String requestId,
        @NotBlank String rollNo,
        @NotBlank String orderNo,
        @NotNull @DecimalMin("0.0") BigDecimal lengthM
) {
}

package com.example.starter.transition.api;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 过渡纸卷合成检验数据提交；首次判定强制降级，仅记录是否达到正品门槛。
 *
 * @param requestId           幂等键
 * @param rollNo              卷号
 * @param measuredBasisWeight 实测克重 g/m²
 * @param measuredAshLevel    实测灰分等级
 * @param measuredTensile     实测抗张指数 N·m/g
 */
public record InspectionRequest(
        @NotBlank String requestId,
        @NotBlank String rollNo,
        @NotNull @DecimalMin("0.0") BigDecimal measuredBasisWeight,
        @NotNull Integer measuredAshLevel,
        @NotNull @DecimalMin("0.0") BigDecimal measuredTensile
) {
}

package com.example.starter.transition.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 过渡卷复议申请；仅首次检验恰达/达到正品门槛且尚未复议时可改判正品一次。
 *
 * @param requestId 幂等键
 * @param rollNo    卷号
 */
public record AppealRequest(
        @NotBlank String requestId,
        @NotBlank String rollNo
) {
}

package com.example.starter.transition.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 归档请求；归档为终态，重复归档返回幂等成功。
 *
 * @param requestId 幂等键
 * @param orderNo   改品种单号
 */
public record ArchiveRequest(
        @NotBlank String requestId,
        @NotBlank String orderNo
) {
}

