package com.example.starter.transition.domain;

/**
 * 改品种单流转状态。
 */
public enum OrderStatus {
    /** 已申请（方式判定完成，尚未执行）。 */
    APPLIED,
    /** 执行中（纸机/清洗资源已占用）。 */
    EXECUTING,
    /** 过渡料已处置（过渡卷登记/检验完成）。 */
    DISPOSED,
    /** 已完成（纸机占用已释放）。 */
    COMPLETED,
    /** 已归档（终态；迟到检验仅登记事件）。 */
    ARCHIVED
}

package com.example.starter.transition.domain;

/**
 * 切换方式：克重差 ≤10%（恰 10% 含）可直接切换，超出须停机清洗。
 */
public enum SwitchMode {
    /** 直接切换。 */
    DIRECT,
    /** 停机清洗（占用清洗窗口）。 */
    STOP_CLEAN
}

package com.example.starter.transition.domain;

/**
 * 过渡纸卷终态等级；登记即 DOWNGRADED，仅一次复议改判可达 QUALIFIED。
 */
public enum FinalGrade {
    /** 强制降级，不得按正品入库。 */
    DOWNGRADED,
    /** 复议改判正品（原降级判定记录保留）。 */
    QUALIFIED
}

package com.example.starter.transition.domain;

/**
 * 过渡纸卷检验状态。
 */
public enum InspectionStatus {
    /** 待检（登记时初始）。 */
    PENDING,
    /** 已检（首次判定完成，强制降级）。 */
    INSPECTED,
    /** 归档后迟到：只登记迟到事件，不产生判定。 */
    LATE
}

