                .andExpect(jsonPath("$.lateEventCount").value(1));
    }

    @Test
    void executeOutsideProcessWindowRejected() throws Exception {
        upsertGrade("g-a", "G-A", "100.00", 3, "800", "1200", "3.0", "4.5", "30.00");
