    @Test
    void inspectionBelowGateCannotAppeal() throws Exception {
        upsertGrade("g-a", "G-A", "100.00", 3, "800", "1200", "3.0", "4.5", "30.00");
        upsertGrade("g-b", "G-B", "110.00", 5, "900", "1100", "3.2", "4.0", "32.00");
