private <T> List<Result<T>> runConcurrently(int threads, Callable<T> task) {
    ExecutorService pool = Executors.newFixedThreadPool(threads);
    CountDownLatch ready = new CountDownLatch(threads);
    CountDownLatch start = new CountDownLatch(1);
    List<Future<Result<T>>> futures = new ArrayList<>();
    for (int i = 0; i < threads; i++) {
        futures.add(pool.submit(() -> {
            ready.countDown();
            start.await(5, TimeUnit.SECONDS);
            try {
                return Result.ok(task.call());
            } catch (Exception e) {
                return Result.fail(e);
            }
        }));
    }
    assertTrue(ready.await(10, TimeUnit.SECONDS));
    start.countDown();
    List<Result<T>> results = new ArrayList<>();
    for (Future<Result<T>> f : futures) {
        results.add(f.get(15, TimeUnit.SECONDS));
    }
    pool.shutdownNow();
    return results;
}
