        start.countDown();
        List<Outcome<T>> results = new ArrayList<>();
        for (Future<Outcome<T>> future : futures) {
            results.add(future.get(20, TimeUnit.SECONDS));
        }
        pool.shutdownNow();
        return results;
    }

    /** 并发任务结果：成功值或捕获的业务异常。 */
    private record Outcome<T>(T value, RuntimeException error) {
    }
